async function forgetScenarioInstall(scenarioId,options={}){
  let matched=installedWorks().filter(item=>
    (item.delta?.scenarios||[]).includes(scenarioId)||
    (item.resources||[]).some(resource=>resource.kind==='scenario')
  );
  let bridge=options.bridge||o.bridge;
  if(options.cleanup&&typeof bridge?.uninstallInstall==='function'){
    for(let item of matched){
      let delta=cloneInstallData(item.delta||{});
      delta.scenarios=(delta.scenarios||[]).filter(id=>id!==scenarioId);
      if(INSTALL_STATE_KEYS.some(key=>(delta[key]||[]).length))await bridge.uninstallInstall(delta);
    }
  }
  for(let item of matched)await removeInstallSnapshot(item.id);
  if(matched.length)saveInstalledWorks(installedWorks().filter(item=>!matched.some(removed=>removed.id===item.id)));
  return matched.length
}
