const SCENARIO_MAX_BYTES=1400000;
function scenarioPackageSummary(raw,file={}){
  let bundle=check(raw);
  if(bundle.kind!=='scenario'||bundle.resources.length!==1||bundle.resources[0]?.kind!=='scenario')throw Error('请选择身份 DLC（scenario）作品包。');
  let resource=bundle.resources[0],scenario=resource.scenario;
  if(!scenario||typeof scenario!=='object')throw Error('DLC 缺少场景清单。');
  if(scenario.exclusiveGroup!=='player-origin')throw Error('DLC 必须属于 player-origin 身份互斥组。');
  if(scenario.allowMidChatSwitch===true)throw Error('身份 DLC 不允许在聊天中途切换。');
  if(scenario.newChatRequired===false)throw Error('身份 DLC 必须要求新建聊天后生效。');
  if(!scenario.id||!scenario.version||!scenario.baseCard)throw Error('DLC 标识、版本或基础卡标识缺失。');
  let openings=Array.isArray(resource.openings)?resource.openings:[],entries=Array.isArray(resource.worldbookEntries)?resource.worldbookEntries:[],relationships=Array.isArray(resource.initialRelationships)?resource.initialRelationships:[],portraits=Array.isArray(resource.portraitProfiles)?resource.portraitProfiles:[];
  if(!openings.length||openings.length>20)throw Error('身份 DLC 必须包含 1～20 个开场白。');
  if(openings.some(item=>!item?.id||!item?.name||!item?.content))throw Error('至少一个开场白缺少 ID、名称或正文。');
  if(!entries.length||entries.length>200)throw Error('身份 DLC 必须包含 1～200 个世界书条目。');
  if(portraits.length>60)throw Error('DLC 人物志最多包含 60 人。');
  if(portraits.some(item=>!item?.name))throw Error('DLC 人物志中有角色缺少姓名。');
  if(portraits.some(item=>Object.prototype.hasOwnProperty.call(item,'portraits')&&(!item.portraits||typeof item.portraits!=='object'||!Object.keys(item.portraits).length)))throw Error('DLC 人物志中有自定义立绘资料为空。');
  let bytes=Number(file.size)||new TextEncoder().encode(JSON.stringify(bundle)).length;
  if(bytes>SCENARIO_MAX_BYTES)throw Error('DLC 作品包超过 1.4MB 上限。');
  return{bundle,resource,scenario,openings,entries,relationships,portraits,bytes,fileName:file.name||''};
}
function formatBytes(bytes){return bytes<1024?`${bytes} B`:`${(bytes/1024).toFixed(bytes>1024*100?0:1)} KB`}
function scenarioUploadPanel(){
  let collection=draft.kind==='collection',source=collection?draft.collectionScenarioBundle:draft.bundle,summary,inputAttr=collection?'data-collection-scenario-file':'data-scenario-file';
  try{if(source)summary=scenarioPackageSummary(source)}catch{}
  if(!summary)return `<section class="scenario-drop"><div class="scenario-seal">籍</div><div><p class="eyebrow">PLAYER ORIGIN DOCUMENT</p><h2>${collection?'加入完整开场 DLC':'导入身份 DLC 文件'}</h2><p>选择 DLC 生成器导出的 <code>.json</code> 完整作品包。将同时携带开场白与初始变量、人物关系、世界书、人物志及角色适配。</p><label class="scenario-file"><input type="file" accept="application/json,.json" ${inputAttr}><span>选择 DLC JSON</span></label><small>必需：开场白、主角身份、关系世界书；仅支持 player-origin 互斥组。</small></div></section>`;
  let {scenario,resource,openings,entries,relationships,portraits,bytes,fileName}=summary;
  return `<section class="scenario-passport"><header><div><p class="eyebrow">DOCUMENT VERIFIED</p><h2>${h(source.metadata?.title||resource.name)}</h2><p>${h(fileName||'已载入的身份文牒')}</p></div><span class="scenario-approved">验讫</span></header><div class="scenario-facts"><span><small>DLC 标识</small><b>${h(scenario.id)}</b></span><span><small>版本</small><b>${h(scenario.version)}</b></span><span><small>基础卡</small><b>${h(scenario.baseCard)}</b></span><span><small>最低版本</small><b>${h(scenario.minBaseVersion||'未限制')}</b></span><span><small>开场白/初始变量</small><b>${openings.length} 个</b></span><span><small>世界书</small><b>${entries.length} 条</b></span><span><small>人物志</small><b>${portraits.length} 人</b></span><span><small>初始关系</small><b>${relationships.length} 条</b></span><span><small>角色适配</small><b>${Number(resource.characterAdaptations?.length||0)} 人</b></span><span><small>包体积</small><b>${formatBytes(bytes)}</b></span></div><div class="scenario-opening-list">${openings.map((opening,index)=>`<span><i>${String(index+1).padStart(2,'0')}</i><b>${h(opening.name)}</b><small>${h(opening.subtitle||'')}</small></span>`).join('')}</div><div class="scenario-rules"><b>完整性预检已通过</b><span>合集安装时仍遵守一局一身份 · 禁止中途切换 · 新建聊天生效</span></div><label class="scenario-file compact"><input type="file" accept="application/json,.json" ${inputAttr}><span>重新选择文件</span></label></section>`;
}
